#include "journal-def.h"
#include "journal-file-util.h"
#include "mmap-cache.h"
#include "rm-rf.h"
#include "tests.h"
#include "time-util.h"

static int open_journal(MMapCache *m, int flags, JournalFile **ret) {
        return journal_file_open(
                        /* fd= */ -EBADF,
                        "test.journal",
                        flags,
                        JOURNAL_COMPRESS,
                        0666,
                        /* compress_threshold_bytes= */ UINT64_MAX,
                        /* metrics= */ NULL,
                        m,
                        /* template= */ NULL,
                        ret);
}

TEST(punch_holes_hash_chain_cycle) {
        _cleanup_(mmap_cache_unrefp) MMapCache *m = NULL;
        char t[] = "/var/tmp/journal-XXXXXX";
        JournalFile *f;
        uint64_t data_offset = 0;
        int fd;

        if (sd_id128_get_machine(NULL) < 0)
                return (void) log_tests_skipped("No valid machine ID found");

        ASSERT_NOT_NULL(m = mmap_cache_new());
        ASSERT_NOT_NULL(mkdtemp(t));
        ASSERT_OK_ERRNO(chdir(t));
        (void) chattr_path(t, FS_NOCOW_FL, FS_NOCOW_FL);

        ASSERT_OK_ZERO(open_journal(m, O_RDWR|O_CREAT, &f));

        for (size_t n = 0; n < 100; n++) {
                _cleanup_free_ char *s = NULL;
                struct iovec iovec;
                struct dual_timestamp ts;

                dual_timestamp_now(&ts);
                ASSERT_OK_ERRNO(asprintf(&s, "RANDOM=%zu", n % 7));
                iovec = IOVEC_MAKE_STRING(s);
                ASSERT_OK_ZERO(journal_file_append_entry(
                                       f, &ts, /* boot_id= */ NULL, &iovec, /* n_iovec= */ 1,
                                       /* seqnum= */ NULL, /* seqnum_id= */ NULL,
                                       /* ret_object= */ NULL, /* ret_offset= */ NULL));
        }
        (void) journal_file_offline_close(f);

        /* Find the head of a non-empty data hash chain */
        ASSERT_OK_ZERO(open_journal(m, O_RDONLY, &f));
        ASSERT_OK(journal_file_map_data_hash_table(f));
        for (uint64_t i = 0; i < le64toh(f->header->data_hash_table_size) / sizeof(HashItem); i++) {
                data_offset = le64toh(f->data_hash_table[i].head_hash_offset);
                if (data_offset != 0)
                        break;
        }
        ASSERT_NE(data_offset, 0u);
        (void) journal_file_close(f);

        /* Corrupt it: make that data object's next_hash_offset point to itself */
        uint64_t self = htole64(data_offset);
        ASSERT_OK_ERRNO(fd = open("test.journal", O_RDWR|O_CLOEXEC));
        ASSERT_EQ(pwrite(fd, &self, sizeof(self), data_offset + offsetof(Object, data.next_hash_offset)),
                  (ssize_t) sizeof(self));
        safe_close(fd);

        ASSERT_OK_ZERO(open_journal(m, O_RDWR, &f));

        /* If the hash chain walk lacks a forward-progress check this never returns */
        alarm(20);
        (void) journal_file_punch_holes(f);
        alarm(0);

        (void) journal_file_close(f);
        (void) rm_rf(t, REMOVE_ROOT|REMOVE_PHYSICAL);
}

DEFINE_TEST_MAIN(LOG_DEBUG);

